begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table reasoning_source(result uuid,reservation jsonb,proposal jsonb);grant select,insert,update on reasoning_source to cuevo_api;
insert into app.intelligence_policies(school_id,version,fixture_enabled,approved_by)values('10000000-0000-4000-8000-000000000001',1,true,'20000000-0000-4000-8000-000000000001')on conflict(school_id)do update set fixture_enabled=true,version=1,data_classification='SCHOOL_CUSTOM_NUMERIC',allowed_actions=array['GUIDED_PRACTICE','REVIEW_FEEDBACK']::text[];
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','9c100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Checked policy reasoning','Synthetic','PUBLISHED');
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001','9c110000-0000-4000-8000-000000000001','9c100000-0000-4000-8000-000000000001','Checked plan',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001','9c120000-0000-4000-8000-000000000001','9c110000-0000-4000-8000-000000000001','Checking example',1,'School explanation');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)values('10000000-0000-4000-8000-000000000001','9c130000-0000-4000-8000-000000000001','9c120000-0000-4000-8000-000000000001','Same readable activity','practice','Explain a check.',1),('10000000-0000-4000-8000-000000000001','9c130000-0000-4000-8000-000000000002','9c120000-0000-4000-8000-000000000001','Same readable activity','practice','Explain a check.',2);
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)values('10000000-0000-4000-8000-000000000001','9c140000-0000-4000-8000-000000000001','9c100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Checking source','School task',10,'61000000-0000-4000-8000-000000000001',2);
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','9c150000-0000-4000-8000-000000000001','9c140000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Synthetic raw answer never reaches model');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
insert into reasoning_source(result)values(internal.release_marking(internal.mark_submission('9c150000-0000-4000-8000-000000000001',3,'Human reviewed',2,0,true),1,false));
select throws_ok($$select internal.begin_teacher_insight_run('bad-prompt-digest',repeat('a',64),(select result from reasoning_source),'{"mode":"FIXTURE","provider":"deterministic-fixture","model":"source-locked-v1","promptId":"next-learning-action","promptVersion":"2","promptDigest":"bad","policyVersion":1,"timeoutMs":30000,"maxTokens":1000,"maxCost":1,"costBasis":"DETERMINISTIC_FIXTURE"}','request')$$,'22023',null,'Unknown prompt content cannot masquerade as approved version');
update reasoning_source set reservation=internal.begin_teacher_insight_run('checked-prompt-reasoning',repeat('b',64),result,'{"mode":"FIXTURE","provider":"deterministic-fixture","model":"source-locked-v1","promptId":"next-learning-action","promptVersion":"2","promptDigest":"1f892110e486d0f8117e53ef9d9cf0a884b7c155821dd8eb1284cef22b9f0de4","policyVersion":1,"timeoutMs":30000,"maxTokens":1000,"maxCost":1,"costBasis":"DETERMINISTIC_FIXTURE"}','request');
select is((select reservation->'context'->'allowedActions'from reasoning_source),'["GUIDED_PRACTICE", "REVIEW_FEEDBACK"]'::jsonb,'Current school actions are frozen in reservation');
reset role;
select is((select tool_trace->0->>'name'from app.intelligence_runs where id=(select(reservation->>'runId')::uuid from reasoning_source)),'teacher_insight.get_authorized_context','Trace names the actual composite authorized retrieval');
select is((select(tool_trace->0->'counts'->>'activities')::integer from app.intelligence_runs where id=(select(reservation->>'runId')::uuid from reasoning_source)),2,'Trace counts saved teacher options without raw instructions');
select throws_ok($$update app.intelligence_runs set tool_trace='[]'::jsonb where id=(select(reservation->>'runId')::uuid from reasoning_source)$$,'55000',null,'Frozen prompt retrieval trace cannot be rewritten');
set local role cuevo_api;
create function pg_temp.reasoning_output(extra jsonb)returns jsonb language sql as $$select jsonb_build_object('evidenceIds',jsonb_build_array(reservation->'context'->'evidenceId'),'facts',jsonb_build_array(((reservation->'context')-'insight'-'allowedActions')||'{"kind":"NUMERIC_RESULT"}'::jsonb),'action','GUIDED_PRACTICE','reason','REVIEW_RECORDED_RESULT','limitation','SINGLE_RESULT_NOT_CAUSAL','selectedActivityId','9c130000-0000-4000-8000-000000000002','analysis',jsonb_build_object('basis','SINGLE_RESULT','resultIds',jsonb_build_array(result),'observationIds','[]'::jsonb,'priorInterventionIds','[]'::jsonb,'interpretation','TEACHER_REVIEW_RECORDED_EVIDENCE','uncertainty','EVIDENCE_NOT_CAUSAL'))||extra from reasoning_source$$;
grant execute on function pg_temp.reasoning_output(jsonb)to cuevo_api;
select throws_ok($$select internal.complete_intelligence_run((select(reservation->>'runId')::uuid from reasoning_source),(select(reservation->>'leaseToken')::uuid from reasoning_source),pg_temp.reasoning_output('{"action":"REVIEW_FEEDBACK"}'),'{"outputTokens":0,"inputTokens":0,"cost":0,"costBasis":"DETERMINISTIC_FIXTURE","latencyMs":1}','request')$$,'22023',null,'Feedback action cannot select practice activity');
select throws_ok($$select internal.complete_intelligence_run((select(reservation->>'runId')::uuid from reasoning_source),(select(reservation->>'leaseToken')::uuid from reasoning_source),pg_temp.reasoning_output(jsonb_build_object('analysis',jsonb_build_object('basis','NATIVE_RESULT_DECLINE','resultIds',jsonb_build_array((select result from reasoning_source)),'observationIds','[]'::jsonb,'priorInterventionIds','[]'::jsonb,'interpretation','TEACHER_REVIEW_RECORDED_EVIDENCE','uncertainty','EVIDENCE_NOT_CAUSAL'))),'{"outputTokens":0,"inputTokens":0,"cost":0,"costBasis":"DETERMINISTIC_FIXTURE","latencyMs":1}','request')$$,'22023',null,'Invented decline without a higher cited result is denied');
update reasoning_source set proposal=internal.complete_intelligence_run((reservation->>'runId')::uuid,(reservation->>'leaseToken')::uuid,pg_temp.reasoning_output('{}'),'{"outputTokens":0,"inputTokens":0,"cost":0,"costBasis":"DETERMINISTIC_FIXTURE","latencyMs":1}','request');
select is((select proposal->>'selectedActivityId'from reasoning_source),'9c130000-0000-4000-8000-000000000002','Chosen exact activity survives duplicate titles');
select is((select proposal->'analysis'->>'basis'from reasoning_source),'SINGLE_RESULT','Validated cited reasoning is retained in receipt');
select internal.decide_recommendation((select(proposal->>'id')::uuid from reasoning_source),'APPROVE','Teacher reviewed the checked proposal.',null,null);
select is((select selected_activity_id::text from app.interventions where recommendation_id=(select(proposal->>'id')::uuid from reasoning_source)),'9c130000-0000-4000-8000-000000000002','Human-approved task retains exact selected source');
reset role;
select is((select grounded_output->>'selectedActivityId'from app.intelligence_runs where id=(select(reservation->>'runId')::uuid from reasoning_source)),'9c130000-0000-4000-8000-000000000002','Immutable run retains model-selected source identity');
select ok(not has_function_privilege('cuevo_api','internal.validate_intelligence_analysis(uuid,jsonb)','EXECUTE'),'Reasoning validator is private to completion');
select ok(not has_function_privilege('cuevo_api','internal.complete_insight_numeric_run(uuid,uuid,jsonb,jsonb,text,uuid,jsonb)','EXECUTE'),'Metadata numeric completion cannot bypass public guards');
update app.intelligence_policies set version=2 where school_id='10000000-0000-4000-8000-000000000001';
set local role cuevo_api;
select is((select count(*)::integer from app.recommendations where id=(select(proposal->>'id')::uuid from reasoning_source)),0,'Changed policy filters stale proposal without failing the current list');
select throws_ok($$select internal.decide_recommendation((select(proposal->>'id')::uuid from reasoning_source),'APPROVE','An old policy cannot authorize a new decision.',null,null)$$,'22023',null,'Stale proposal decision remains denied by current policy');
select is((internal.begin_teacher_insight_run('new-approved-policy',repeat('c',64),(select result from reasoning_source),'{"mode":"FIXTURE","provider":"deterministic-fixture","model":"source-locked-v1","promptId":"next-learning-action","promptVersion":"2","promptDigest":"1f892110e486d0f8117e53ef9d9cf0a884b7c155821dd8eb1284cef22b9f0de4","policyVersion":2,"timeoutMs":30000,"maxTokens":1000,"maxCost":1,"costBasis":"DETERMINISTIC_FIXTURE"}','request')->>'state'),'NEW','Fresh analysis uses the new approved policy after stale proposal filtering');
reset role;
select*from finish();rollback;
